size_t measure_error_code(string_view message) {
  (void)error_size_;
  static const char SEP[] = ": ";
  static const char ERROR_STR[] = "error ";
  error_size_ = static_cast<int>(sizeof(SEP) + sizeof(ERROR_STR) - 2);
  auto abs_value = static_cast<uint32_or_64_or_128_t<int>>(error_code_);
