#include <locale>
#include <fmt/format.h>
#include <fmt/printf.h>
struct sep : std::numpunct<char> {
  std::string do_grouping() const override { return "\3"; }
  char do_thousands_sep() const override { return ','; }
};
int main() {
  std::locale loc(std::locale(), new sep);
  fmt::print("     X = {}\n", fmt::format(loc, "{:19.3Lf}", -119.921L));
  fmt::print("     Y = {}\n", fmt::format(loc, "{:19.3Lf}", 2194.139L));
  fmt::print("     Z = {}\n", fmt::format(loc, "{:19.3Lf}", -57.639L));
  fmt::print("    VX = {}\n", fmt::format(loc, "{:19.3Lf}", -5.980L));
  fmt::print("    VY = {}\n", fmt::format(loc, "{:19.3Lf}", -2.119L));
  fmt::print("    VZ = {}\n", fmt::format(loc, "{:19.3Lf}", 0.295L));
}
EOF
